package com.portfolio.features.skill.service; import com.portfolio.common.exception.*; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.skill.dto.*; import com.portfolio.features.skill.entity.Skill; import com.portfolio.features.skill.repository.SkillRepository; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class SkillService {private final SkillRepository repo;private final PortfolioAccessService access;@Transactional(readOnly=true) public List<Skill> list(AppUser u){return repo.findByPortfolioIdOrderBySortOrderAscNameAsc(access.mine(u).getId());}@Transactional public Skill create(AppUser u,SkillRequest r){var p=access.mine(u);String name=r.name().trim();if(repo.duplicate(p.getId(),name,null))throw new ConflictException("Skill already exists.");Skill s=new Skill();s.setPortfolio(p);apply(s,r,name);return repo.save(s);}@Transactional public Skill update(AppUser u,UUID id,SkillRequest r){Skill s=owned(u,id);String name=r.name().trim();if(repo.duplicate(s.getPortfolio().getId(),name,id))throw new ConflictException("Skill already exists.");apply(s,r,name);return s;}@Transactional public void delete(AppUser u,UUID id){repo.delete(owned(u,id));}private Skill owned(AppUser u,UUID id){Skill s=repo.findById(id).orElseThrow(()->new NotFoundException("Skill not found."));access.owned(u,s.getPortfolio().getId());return s;}private void apply(Skill s,SkillRequest r,String n){s.setName(n);s.setCategory(r.category()==null?null:r.category().trim());s.setSortOrder(r.sortOrder());}}
